<?php
session_start();
require_once 'GEX-EC-05-SCRUM-Sprint-2-Desarrollo-ConfiguracionDeConexion-20261005-V1.0.php';
if (!isset($_SESSION['usuario_id']) || ($_SESSION['usuario_rol'] ?? '') !== 'Agente') { header('Location: GEX-EC-05-SCRUM-Sprint-2-Desarrollo-PanelPrincipal-20261005-V1.0.php'); exit(); }
$mensaje = ''; $mensajeError = '';
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: filter_input(INPUT_POST, 'solicitud_id', FILTER_VALIDATE_INT);
$transiciones = ['Nuevo' => 'En Proceso', 'En Proceso' => 'Resuelta'];

if ($_SERVER['REQUEST_METHOD'] === 'POST' && $id) {
    $stmt = $pdo->prepare('SELECT id, titulo, estado, usuario_id FROM solicitudes WHERE id = ? AND agente_id = ?');
    $stmt->execute([$id, $_SESSION['usuario_id']]);
    $solicitud = $stmt->fetch(PDO::FETCH_ASSOC);
    if (!$solicitud) { $mensajeError = 'La solicitud no está asignada a tu cuenta.'; }
    elseif (isset($_POST['agregar_comentario'])) {
        $comentario = trim($_POST['comentario'] ?? '');
        if ($comentario === '') { $mensajeError = 'El comentario no puede estar vacío.'; }
        else { $stmt = $pdo->prepare('INSERT INTO comentarios_trabajo (solicitud_id, agente_id, comentario) VALUES (?, ?, ?)'); $stmt->execute([$id, $_SESSION['usuario_id'], $comentario]); $mensaje = 'Comentario registrado. No puede editarse después de creado.'; }
    } elseif (isset($_POST['cambiar_estado'])) {
        $nuevoEstado = $_POST['nuevo_estado'] ?? '';
        if (!isset($transiciones[$solicitud['estado']]) || $transiciones[$solicitud['estado']] !== $nuevoEstado) { $mensajeError = 'Transición de estado no permitida.'; }
        else {
            $pdo->beginTransaction();
            try {
                $stmt = $pdo->prepare('UPDATE solicitudes SET estado = ? WHERE id = ? AND agente_id = ?'); $stmt->execute([$nuevoEstado, $id, $_SESSION['usuario_id']]);
                $stmt = $pdo->prepare("INSERT INTO historial_estados (solicitud_id, usuario_id, rol, estado_anterior, estado_nuevo, motivo) VALUES (?, ?, 'Agente', ?, ?, NULL)"); $stmt->execute([$id, $_SESSION['usuario_id'], $solicitud['estado'], $nuevoEstado]);
                $stmt = $pdo->prepare("INSERT INTO notificaciones (usuario_id, solicitud_id, tipo, mensaje) VALUES (?, ?, 'estado', ?)"); $stmt->execute([$solicitud['usuario_id'], $id, 'La solicitud #' . $id . ' cambió a ' . $nuevoEstado . '.']);
                $pdo->commit(); $mensaje = 'Estado actualizado y registrado en el historial.';
            } catch (Throwable $e) { $pdo->rollBack(); $mensajeError = 'No fue posible cambiar el estado.'; }
        }
    }
}

$stmt = $pdo->prepare('SELECT id, titulo, estado, prioridad, fecha_actualizacion FROM solicitudes WHERE agente_id = ? ORDER BY FIELD(prioridad, \'Alta\', \'Media\', \'Baja\'), fecha_actualizacion DESC'); $stmt->execute([$_SESSION['usuario_id']]); $asignadas = $stmt->fetchAll(PDO::FETCH_ASSOC);
$detalle = null; $comentarios = []; $historial = [];
if ($id) { $stmt = $pdo->prepare('SELECT id, titulo, descripcion, categoria, estado, prioridad, fecha_creacion, fecha_actualizacion FROM solicitudes WHERE id = ? AND agente_id = ?'); $stmt->execute([$id, $_SESSION['usuario_id']]); $detalle = $stmt->fetch(PDO::FETCH_ASSOC); if ($detalle) { $stmt = $pdo->prepare('SELECT c.comentario, c.fecha_creacion, u.nombre FROM comentarios_trabajo c INNER JOIN usuarios u ON u.id = c.agente_id WHERE c.solicitud_id = ? ORDER BY c.fecha_creacion DESC'); $stmt->execute([$id]); $comentarios = $stmt->fetchAll(PDO::FETCH_ASSOC); $stmt = $pdo->prepare('SELECT estado_anterior, estado_nuevo, motivo, fecha_cambio, u.nombre FROM historial_estados h INNER JOIN usuarios u ON u.id = h.usuario_id WHERE h.solicitud_id = ? ORDER BY h.fecha_cambio DESC'); $stmt->execute([$id]); $historial = $stmt->fetchAll(PDO::FETCH_ASSOC); } }
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Mis atenciones - Soporte</title><link rel="stylesheet" href="GEX-EC-05-SCRUM-Sprint-2-Desarrollo-EstilosDeInterfaz-20261005-V1.0.css"></head><body><div class="dashboard-layout"><?php include 'GEX-EC-05-SCRUM-Sprint-2-Desarrollo-MenuDeNavegacion-20261005-V1.0.php'; ?><div class="main-wrapper"><header class="topbar"><div class="topbar-title"><h2>Mis Atenciones</h2></div><div class="topbar-user"><span><strong><?php echo htmlspecialchars($_SESSION['usuario_nombre']); ?></strong></span><span class="user-badge">Agente</span><a href="GEX-EC-05-SCRUM-Sprint-2-Desarrollo-CierreDeSesion-20261005-V1.0.php" class="btn-logout">Cerrar Sesión</a></div></header><main class="content-area">
<?php if ($mensaje): ?><div class="notice-success"><?php echo htmlspecialchars($mensaje); ?></div><?php endif; ?><?php if ($mensajeError): ?><div class="notice-error"><?php echo htmlspecialchars($mensajeError); ?></div><?php endif; ?>
<?php if (!$detalle): ?><div class="page-heading"><div><h1>Solicitudes asignadas</h1><p>Selecciona una solicitud para documentar avances y cambiar su estado.</p></div></div><div class="ui-card"><table class="modern-table"><thead><tr><th>ID</th><th>Título</th><th>Prioridad</th><th>Estado</th><th>Última actualización</th><th></th></tr></thead><tbody><?php if (!$asignadas): ?><tr><td colspan="6" class="empty-table">No tienes solicitudes asignadas.</td></tr><?php else: ?><?php foreach ($asignadas as $s): ?><tr><td>#<?php echo (int) $s['id']; ?></td><td><?php echo htmlspecialchars($s['titulo']); ?></td><td><?php echo htmlspecialchars($s['prioridad']); ?></td><td><?php echo htmlspecialchars($s['estado']); ?></td><td><?php echo htmlspecialchars(date('d/m/Y H:i', strtotime($s['fecha_actualizacion']))); ?></td><td><a class="badge-btn" href="GEX-EC-05-SCRUM-Sprint-2-Desarrollo-AtencionDeAgente-20261005-V1.0.php?id=<?php echo (int) $s['id']; ?>">Atender</a></td></tr><?php endforeach; ?><?php endif; ?></tbody></table></div>
<?php else: ?><a href="GEX-EC-05-SCRUM-Sprint-2-Desarrollo-AtencionDeAgente-20261005-V1.0.php" class="back-link">← Volver a mis atenciones</a><div class="ui-card detail-card"><div class="detail-header"><div><span class="detail-id">Solicitud #<?php echo (int) $detalle['id']; ?></span><h1><?php echo htmlspecialchars($detalle['titulo']); ?></h1></div><span class="status-badge status-<?php echo strtolower(str_replace(' ', '-', $detalle['estado'])); ?>"><?php echo htmlspecialchars($detalle['estado']); ?></span></div><p><?php echo nl2br(htmlspecialchars($detalle['descripcion'])); ?></p><div class="agent-actions"><form method="POST"><input type="hidden" name="solicitud_id" value="<?php echo (int) $detalle['id']; ?>"><select name="nuevo_estado" required><option value="">Cambiar estado</option><?php if (isset($transiciones[$detalle['estado']])): ?><option value="<?php echo $transiciones[$detalle['estado']]; ?>"><?php echo $transiciones[$detalle['estado']]; ?></option><?php endif; ?></select><button class="badge-btn" name="cambiar_estado">Guardar estado</button></form></div><hr><h3>Comentarios de trabajo</h3><form method="POST" class="comment-form"><input type="hidden" name="solicitud_id" value="<?php echo (int) $detalle['id']; ?>"><textarea name="comentario" rows="3" required placeholder="Describe el avance realizado..."></textarea><button class="btn-primary-link" name="agregar_comentario">Registrar comentario</button></form><?php foreach ($comentarios as $c): ?><div class="comment-item"><strong><?php echo htmlspecialchars($c['nombre']); ?></strong><small><?php echo htmlspecialchars(date('d/m/Y H:i', strtotime($c['fecha_creacion']))); ?></small><p><?php echo nl2br(htmlspecialchars($c['comentario'])); ?></p></div><?php endforeach; ?><h3>Historial de estados</h3><?php foreach ($historial as $h): ?><div class="history-item"><strong><?php echo htmlspecialchars($h['estado_anterior'] ?: 'Inicio'); ?> → <?php echo htmlspecialchars($h['estado_nuevo']); ?></strong><small><?php echo htmlspecialchars($h['nombre']); ?> · <?php echo htmlspecialchars(date('d/m/Y H:i', strtotime($h['fecha_cambio']))); ?></small></div><?php endforeach; ?></div><?php endif; ?></main></div></div></body></html>
